function validateEmailClassification(raw) {
  let value;
  try { value=typeof raw==='string'?JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'')):raw; } catch { value=null; }
  const purposes=['support','upgrade','quotation','billing','meeting','incomplete_inquiry'];
  const relationships=['employee','customer','lead','supplier','wholesale_partner'];
  if(!value||typeof value!=='object'||Array.isArray(value)||!(value.purpose===null||purposes.includes(value.purpose))||!(value.relationship===null||relationships.includes(value.relationship))||typeof value.purpose_confidence!=='number'||!Number.isFinite(value.purpose_confidence)||value.purpose_confidence<0||value.purpose_confidence>1||typeof value.relationship_confidence!=='number'||!Number.isFinite(value.relationship_confidence)||value.relationship_confidence<0||value.relationship_confidence>1||typeof value.needs_review!=='boolean'||typeof value.reason!=='string') {
    return {purpose:null,relationship:null,purpose_confidence:0,relationship_confidence:0,purpose_needs_review:true,relationship_needs_review:true,needs_review:true,reason:'AI classification was unavailable or invalid; owner review required.'};
  }
  return {purpose:value.purpose,relationship:value.relationship,purpose_confidence:value.purpose_confidence,relationship_confidence:value.relationship_confidence,purpose_needs_review:typeof value.purpose_needs_review==='boolean'?value.purpose_needs_review:value.needs_review,relationship_needs_review:typeof value.relationship_needs_review==='boolean'?value.relationship_needs_review:value.needs_review,needs_review:value.needs_review,reason:value.reason.slice(0,600)};
}
const input=$('Load Classification Input').first().json.classification_input;if(!input?.message_id||!input.fingerprint)throw new Error('Incoming classification identity missing');return [{json:{message_id:input.message_id,fingerprint:input.fingerprint,result:validateEmailClassification($json.text||$json.output||null)}}];

const f = $('Find Customer').item.json;
const ctx = $('Load Customer Context').item.json;
const prev = $('Format Email Chain').item.json;
function list(arr, fn) { if (!arr || !arr.length) return 'none'; return arr.map(fn).join('; '); }
let contextText = '';
const emailBrain=$('Load Email Brain').first().json.email_brain;
if(emailBrain?.identity&&String(emailBrain.identity).toLowerCase()!==String(prev.sender).toLowerCase())throw new Error('A newer sender changed this conversation; do not mix customer histories.');
const mc = Number(f.match_count || 0);
if (mc === 1 && f.customer) {
  const c = f.customer;
  contextText = 'Customer: ' + c.name + ' <' + c.email + '> (matched via ' + c.via + ')\n';
  contextText += 'Contacts: ' + list(ctx.contacts, x => x.name + ' <' + x.email + '>' + (x.phone ? ' ' + x.phone : '')) + '\n';
  contextText += 'Sites: ' + list(ctx.sites, x => x.name + ' (' + x.address + ')') + '\n';
  contextText += 'Equipment: ' + list(ctx.equipment, x => x.name + (x.model ? ' model ' + x.model : '') + (x.serial_number ? ' S/N ' + x.serial_number : '') + (x.battery_configuration ? ' [' + x.battery_configuration + ']' : '')) + '\n';
  contextText += 'Recent purchases: ' + list(ctx.purchases, x => x.name + ' on ' + x.occurred_on + (x.amount != null ? ' $' + x.amount : '')) + '\n';
  contextText += 'Recent services: ' + list(ctx.services, x => x.name + ' on ' + x.occurred_on + (x.notes ? ' - ' + x.notes : ''));
} else if (mc > 1) {
  contextText = 'WARNING: multiple CRM customers match this sender email. Do not reference any specific account details; answer generally and note the account needs manual review.';
}
const classification=$('Save AI Classification').first().json.classification;
contextText+='\nCURRENT SAVED CLASSIFICATION: '+JSON.stringify(classification);
return [{ json: { classification, contextText:contextText+'\n\nEMAIL BRAIN (historical evidence and confirmed examples):\n'+JSON.stringify(emailBrain), customerMatched: mc === 1, matchCount: mc, subject: prev.subject, sender: prev.sender, threadText: prev.threadText, messageId: prev.messageId } }];
